?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SmartToolz Background Remover</title><meta name="description" content="Remove image backgrounds quickly in your browser with SmartToolz."><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=Material+Symbols+Rounded:opsz,wght,FILL,GRAD@20..48,500,0,0&display=swap" rel="stylesheet"><style>:root{--p:#635bff;--p2:#8b7cff;--ink:#151824;--muted:#777f90;--line:#e5e8ef;--bg:#f6f7fb}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,system-ui,sans-serif}.material-symbols-rounded{font-size:20px;vertical-align:middle}.app{width:min(1120px,calc(100% - 28px));margin:auto;padding:18px 0 30px}.head{display:flex;justify-content:space-between;align-items:end;gap:16px;margin-bottom:12px}.ey{font-size:10px;font-weight:900;color:#5b53d8;letter-spacing:.5px}.head h1{margin:6px 0 4px;font-size:clamp(29px,4vw,46px);line-height:1.02;letter-spacing:-2.2px}.head p{margin:0;font-size:11px;color:var(--muted)}.guide{padding:9px 12px;border:1px solid #dedbff;border-radius:10px;background:#fff;color:#554bd5;font-size:9px;font-weight:900;white-space:nowrap}.tool{overflow:hidden;background:#fff;border:1px solid var(--line);border-radius:20px;box-shadow:0 14px 45px rgba(30,35,75,.07)}.top{height:50px;display:flex;align-items:center;justify-content:space-between;padding:0 13px;border-bottom:1px solid var(--line)}.state{display:flex;align-items:center;gap:8px;font-size:9px;font-weight:850}.dot{width:7px;height:7px;border-radius:50%;background:#16a34a;box-shadow:0 0 0 4px #dcfce7}.actions{display:flex;gap:6px}.ghost{border:1px solid var(--line);background:#fff;border-radius:8px;padding:7px 10px;font-size:8px;font-weight:850;color:#515a6c}.stage{min-height:0;height: