;align-items:center;margin-bottom:8px}.resulthead b{font-size:11px}.resulthead span{font-size:8px;color:var(--muted)}.compare{position:relative;min-height:230px;height:300px;overflow:hidden;border-radius:12px;background:#ddd}.compare img{display:block;width:100%;height:100%;max-height:500px;object-fit:contain}.compare .after{position:absolute;inset:0;width:50%;overflow:hidden;border-right:2px solid #fff}.compare .after img{width:100%;height:100%;object-fit:contain}.compare input{position:absolute;inset:0;width:100%;opacity:0;cursor:ew-resize}.tip{text-align:center;margin-top:7px;color:#9299a6;font-size:8px}@media(max-width:650px){.app{width:calc(100% - 14px);padding-top:10px}.head{display:block}.head h1{letter-spacing:-1.6px}.guide{display:inline-flex;margin-top:9px}.stage{height:390px;padding:10px}.drop{padding:30px 14px}.canvas{height:368px}.canvas canvas{max-height:330px;max-width:96%}.footerbar{flex-direction:column}.footerbar button{width:100%}.compare{height:230px;min-height:190px}}</style></head><body><?php require_once __DIR__.'/../header.php'; ?><main class="app"><header class="head"><div><div class="ey">SMARTTOOLZ • BACKGROUND REMOVER</div><h1>Remove the background. <span style="color:var(--p)">Keep the subject.</span></h1><p>One clear action. Fast browser processing. Download when it’s done.</p></div><a class="guide" href="/knowledge-base/image-background-remover/article/">How to use this tool</a></header><section class="tool"><div class="top"><div class="state"><i class="dot"></i><span id="status">Ready to remove</span></div><div class="actions"><button class="ghost" id="new">New image</button></div></div><div class="stage" id="stage"><div class="drop" id="drop"><div class="icon"><span class="material-symbols-rounded">content_cut</span></div><h2>Remove background</h2><p>Choose an image and SmartToolz will automatically isolate the subject.</p><label class="choose"><span class="material-symbols-rounded">upload_file</span> Choose image<input id="picker" hidden type="file" accept="image/png,image/jpeg,image/webp"></label><div class="sub">PNG • JPG • WebP</div></div><div class="canvas" id="canvas"><canvas id="out"></canvas><div class="busy" id="busy"><div class="busyrow"><span>Removing background…</span><span id="pct">0%</span></div><div class="bar"><i id="fill"></i></div></div></div></div><div class="footerbar" id="footer"><button id="again">↺ Try another</button><button id="download" class="primary">↓ Download PNG</button></div><div class="result" id="result"><div class="resulthead"><b>Before / After</b><span>Drag the slider</span></div><div class="compare"><img id="before" alt="Original"><div class="after"><img id="after" alt="Background removed"></div><input id="slider" type="range" min="0" max="100" value="50"></div><div class="tip">Background removed — compare the original and result.</div></div></section></main><script type="module">import{removeBackground}from'https://cdn.jsdelivr.net/npm/@imgly/background-removal@1.7.0/+esm';const $=id=>document.getElementById(id),picker=$('picker'),drop=$('drop'),canvasWrap=$('canvas'),canvas=$('out'),ctx=canvas.getContext('2d'),busy=$('busy'),fill=$('fill'),pct=$('pct'),status=$('status'),footer=$('footer'),result=$('result'),before=$('before'),after=$('after');let outUrl='',sourceUrl='';function reset(){picker.value='';drop.style.display='block';canvasWrap.style.display='none';busy.style.display='none';footer.style.display='none';result.style.display='none';status.textContent='Ready to remove';if(outUrl)URL.revokeObjectURL(outUrl);if(sourceUrl)URL.revokeObjectURL(sourceUrl);outUrl='';sourceUrl=''}async function img(src){return new Promise((r,j)=>{const i=new Image();i.onload=()=>r(i);i.onerror=j;i.src=src})}async function run(file){if(!file||!/^image\/(png|jpeg|webp)$/.test(file.type))return;drop.style.display='none';canvasWrap.style.display='flex';busy.style.display='block';footer.style.display='none';result.style.display='none';sourceUrl=URL.createObjectURL(file);before.src=sourceUrl;try{const blob=await removeBackground(file,{model:'small',output:{format:'image/png',quality:1},progress:(k,c,t)=>{const p=t?Math.max(5,Math.min(96,Math.round(c/t*90)+5)):5;fill.style.width=p+'%';pct.textContent=p+'%';status.textContent='Removing background'}});outUrl=URL.createObjectURL(blob);const im=await img(outUrl),w=im.naturalWidth,h=im.naturalHeight;canvas.width=w;canvas.height=h;ctx.clearRect(0,0,w,h);ctx.drawImage(im,0,0,w,h);after.src=outUrl;fill.style.width='100%';pct.textContent='100%';busy.style.display='none';footer.style.display='flex';result.style.display='block';status.textContent='Background removed'}catch(e){console.error(e);busy.style.display='none';status.textContent='Could not process image'}}picker.onchange=e=>{const f=e.target.files?.[0];picker.value='';run(f)};drop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('drag')});drop.addEventListener('dragleave',()=>drop.classList.remove('drag'));drop.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('drag');run(e.dataTransfer.files?.[0])});$('new').onclick=reset;$('again').onclick=reset;$('download').onclick=()=>{if(!outUrl)return;const a=document.createElement('a');a.href=outUrl;a.download='smarttoolz-background-removed.png';a.click()};$('slider').oninput=e=>{$('after').parentElement.style.width=e.target.value+'%'};window.addEventListener('beforeunload',()=>{if(outUrl)URL.revokeObjectURL(outUrl);if(sourceUrl)URL.revokeObjectURL(sourceUrl)});</script></body></html>